const {JSDOM,VirtualConsole}=require('jsdom'),assert=require('node:assert/strict'),fs=require('fs'),{webcrypto,createHash}=require('node:crypto');
const shell=JSON.parse(fs.readFileSync(0,'utf8')),hash=s=>createHash('sha256').update(s).digest('hex'),children=[],errors=[],vc=new VirtualConsole();vc.on('jsdomError',e=>errors.push(e.message));
(async()=>{let outer;outer=new JSDOM(shell,{url:'http://localhost/book/index.html',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(w){w.HTMLMediaElement.prototype.pause=()=>{};w.HTMLMediaElement.prototype.load=function(){this.selectionReset={connected:this.isConnected,base:this.ownerDocument.baseURI}};w.HTMLMediaElement.prototype.play=function(){if(this.dataset.requiresLoad==='true'&&!this.selectionReset?.connected)return Promise.reject(new w.DOMException('Media load rejected by URL safety check','NotSupportedError'));w.nativePlays=(w.nativePlays||0)+1;return Promise.resolve()};w.TextEncoder=TextEncoder;Object.defineProperty(w.crypto,'subtle',{value:webcrypto.subtle});Object.defineProperty(w.HTMLIFrameElement.prototype,'srcdoc',{configurable:true,set(value){const frame=this;frame.dispatchEvent(new w.Event('load'));const child=new JSDOM(value,{url:'http://localhost/book/media/',runScripts:'dangerously',pretendToBeVisual:true,virtualConsole:vc,beforeParse(c){Object.defineProperty(c,'parent',{value:w});c.ResizeObserver=class{observe(){}unobserve(){}disconnect(){}};c.scrollTo=()=>{};c.HTMLMediaElement.prototype.pause=()=>{}}});children.push(child);Object.defineProperty(frame,'contentDocument',{configurable:true,get:()=>child.window.document});Object.defineProperty(frame,'contentWindow',{configurable:true,get:()=>child.window});setTimeout(()=>frame.dispatchEvent(new w.Event('load')),0)}})}});const w=outer.window,api=w.StudySharedFrame;assert.ok(api);assert.equal(errors.length,0);
assert.equal(typeof api.mountFront,'function');assert.equal(typeof api.attachComplete,'function');assert.equal(typeof api.cancel,'function');
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function flipped(answer){for(let i=0;i<150&&w.document.getElementById('study-flip').getAttribute('aria-pressed')!==String(answer);i++)await pause(10);assert.equal(w.document.getElementById('study-flip').getAttribute('aria-pressed'),String(answer))}
function full(id,token){const code='window.runs=(window.runs||0)+1;',sides=['完整正面 ','完整背面 '].map(label=>'<!doctype html><html><head><base href="../media/"></head><body><main>'+label+id+'</main><script>'+code+'</script></body></html>'),prepared={sides:sides.map(source=>({html:source,registry:{},children:[],proof:{source_sha256:hash(source),expanded_sha256:hash(source)}})),modules:{},source_wrapper_sha256:hash('wrapper:'+id),source_payload_sha256:hash(JSON.stringify(sides))};return{id,token,requestedAt:0,base:'http://localhost/book/media/',baseTags:['<base href="../media/">','<base href="../media/">'],sides,prepared,policy:{external:{},inline:[{source:code,sha256:hash(code)}]},deliveryBinding:{index_sha256:hash('index'),full_prepared_sha256:hash(JSON.stringify(prepared)),source_wrapper_sha256:prepared.source_wrapper_sha256,source_payload_sha256:prepared.source_payload_sha256,source_front_sha256:hash(sides[0]),wrapper_url:'cards/'+id+'.html'}}}
function front(packet){const p=JSON.parse(JSON.stringify(packet));p.frontOnly=true;p.sides=p.sides.slice(0,1);p.baseTags=p.baseTags.slice(0,1);p.prepared.sides=p.prepared.sides.slice(0,1);return p}
function visible(){return w.document.getElementById('study-side')}
let next=1,p=full('one',next++);assert.equal(await api.mountFront(front(p)),true);const first=visible(),firstDoc=first.contentDocument,firstWindow=first.contentWindow;assert.ok(firstDoc.body.textContent.includes('完整正面 one'));assert.equal(firstWindow.runs,1);assert.ok(!Array.from(w.document.querySelectorAll('iframe')).some(f=>f.contentDocument?.body.textContent.includes('完整背面 one')),'front-only invented or prepared a back');
w.document.getElementById('study-flip').click();await pause(30);assert.equal(visible(),first,'flip exposed an incomplete back before attachment');assert.equal(w.document.getElementById('study-flip').disabled,true);assert.equal(await api.attachComplete(p),true);await flipped(true);assert.equal(first.contentDocument,firstDoc,'attachment rebuilt the complete front');assert.equal(firstWindow.runs,1);assert.ok(visible().contentDocument.body.textContent.includes('完整背面 one'));assert.equal(await api.attachComplete(p),true,'the same verified attachment must be idempotent');w.document.getElementById('study-flip').click();await flipped(false);assert.equal(visible(),first);assert.equal(firstWindow.runs,1);assert.equal(w.document.querySelectorAll('iframe').length,2);
const early=full('early',next++),earlyFront=api.mountFront(front(early));assert.equal(await api.attachComplete(early),true,'a valid early attachment must not cancel front preparation');assert.equal(await earlyFront,true);assert.ok(visible().contentDocument.body.textContent.includes('完整正面 early'));w.document.getElementById('study-flip').click();await flipped(true);
const changes=[q=>q.deliveryBinding.index_sha256=hash('wrong-index'),q=>q.deliveryBinding.full_prepared_sha256=hash('wrong-full'),q=>q.deliveryBinding.source_wrapper_sha256=hash('wrong-wrapper'),q=>q.deliveryBinding.source_payload_sha256=hash('wrong-payload'),q=>q.deliveryBinding.source_front_sha256=hash('wrong-front'),q=>q.deliveryBinding.wrapper_url='cards/wrong.html',q=>q.base='http://localhost/other/media/',q=>q.prepared.modules={different:{src:'never.js',sha256:hash('unused')}},q=>q.sides[0]+='changed',q=>q.prepared.sides[0].html+='changed',q=>q.baseTags[0]='<base href="other/">',q=>q.prepared.source_wrapper_sha256=hash('different-source'),q=>q.prepared.source_payload_sha256=hash('different-payload')];
for(let i=0;i<changes.length;i++){const original=full('invalid-'+i,next++);await api.mountFront(front(original));const shown=visible(),bad=JSON.parse(JSON.stringify(original));changes[i](bad);await assert.rejects(api.attachComplete(bad),/attachment|binding|front|source|base|module/i);assert.equal(visible(),shown);assert.ok(shown.contentDocument.body.textContent.includes('完整正面 invalid-'+i));assert.equal(await api.attachComplete({...original,id:'obsolete'}),false);assert.equal(await api.attachComplete({...original,token:original.token-1}),false)}
const beforeCancel=visible(),reserved=next++;assert.equal(api.cancel(reserved),true);assert.equal(visible(),beforeCancel,'cancel erased the complete visible face');assert.equal(api.cancel(reserved),false);const reservedPacket=full('reserved',reserved);assert.equal(await api.mountFront(front(reservedPacket)),true,'mount must accept the token reserved by cancel');assert.equal(api.cancel(reserved),false,'same-token cancellation invalidated the new session');assert.equal(await api.attachComplete(reservedPacket),true);
const digestOriginal=w.crypto.subtle.digest.bind(w.crypto.subtle),held=[];w.crypto.subtle.digest=(...args)=>new Promise(resolve=>held.push(()=>digestOriginal(...args).then(resolve)));const oldA=full('A',next++),lateA=api.mountFront(front(oldA));await pause(10);assert.equal(held.length,2);w.crypto.subtle.digest=digestOriginal;const B=full('B',next++);api.cancel(B.token);assert.equal(await api.mountFront(front(B)),true);const newA=full('A',next++);api.cancel(newA.token);assert.equal(await api.mountFront(front(newA)),true);const winner=visible();for(const release of held)release();assert.equal(await lateA,false);assert.equal(await api.attachComplete(oldA),false,'old A attachment revived after A→B→A');assert.equal(visible(),winner);assert.ok(winner.contentDocument.body.textContent.includes('完整正面 A'));assert.equal(await api.attachComplete(newA),true);
const waiting=full('waiting',next++);await api.mountFront(front(waiting));w.document.getElementById('study-flip').click();await pause(20);const newer=full('newer',next++);api.cancel(newer.token);assert.equal(await api.mountFront(front(newer)),true);assert.equal(await api.attachComplete(waiting),false);assert.ok(visible().contentDocument.body.textContent.includes('完整正面 newer'));assert.equal(await api.mountFront(front({...waiting,token:newer.token-1})),false);
const legacy=full('legacy',next++);delete legacy.deliveryBinding;assert.equal(await api.mount(legacy),true,'legacy complete mounts must not require front bindings');w.document.getElementById('study-flip').click();await flipped(true);assert.ok(visible().contentDocument.body.textContent.includes('完整背面 legacy'));assert.deepEqual(errors,[]);for(const child of children)child.window.close();outer.window.close();console.log(JSON.stringify({bindingMismatchCases:changes.length,oneFaceProtocol:true,frontPreserved:true,cancellationABA:true,legacy:true,pass:true}));})().catch(e=>{console.error(e);process.exit(1)});
